import{_ as t,o as a,c as i,a7 as d}from"./chunks/framework.BCbKzsgW.js";const p=JSON.parse('{"title":"延迟任务与到期处理","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/task-scheduling/triggers/delayed-tasks.md","filePath":"development/common/task-scheduling/triggers/delayed-tasks.md","lastUpdated":1793441194000}'),r={name:"development/common/task-scheduling/triggers/delayed-tasks.md"};function o(s,e,l,n,h,c){return a(),i("div",null,[...e[0]||(e[0]=[d('<h1 id="yan-chi-ren-wu-yu-dao-qi-chu-li" tabindex="-1">延迟任务与到期处理 <a class="header-anchor" href="#yan-chi-ren-wu-yu-dao-qi-chu-li" aria-label="Permalink to &quot;延迟任务与到期处理&quot;">​</a></h1><p>延迟任务在某个时间之后获得执行资格。例如订单创建 30 分钟后，系统检查它是否仍然待支付。任务的计划时间决定何时开始检查，当前业务状态决定动作是否成立。</p><h2 id="ji-hua-shi-jian-yu-shi-ji-kai-shi-shi-jian" tabindex="-1">计划时间与实际开始时间 <a class="header-anchor" href="#ji-hua-shi-jian-yu-shi-ji-kai-shi-shi-jian" aria-label="Permalink to &quot;计划时间与实际开始时间&quot;">​</a></h2><p>建议区分三个时间：</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td><code>scheduled_at</code></td><td>原始计划时间，用来衡量业务时效</td></tr><tr><td><code>available_at</code></td><td>下一次允许领取的时间，重试时可以后移</td></tr><tr><td><code>started_at</code></td><td>本次尝试真正开始处理的时间</td></tr></tbody></table><p>后移重试时间时保留原始计划时间，否则延迟指标会随着每次重试被“刷新”。是否允许提前执行、可以晚多久、晚到后是否仍然有价值，都应由业务规则决定。</p><h2 id="deng-dai-ji-zhi" tabindex="-1">等待机制 <a class="header-anchor" href="#deng-dai-ji-zhi" aria-label="Permalink to &quot;等待机制&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>等待在哪里</th><th>主要边界</th></tr></thead><tbody><tr><td>进程内定时器</td><td>内存</td><td>进程重启后需要从持久化记录重建</td></tr><tr><td>数据库到期扫描</td><td>带执行时间的任务表</td><td>索引、扫描间隔和领取竞争</td></tr><tr><td>按时间排序的集合</td><td>按到期时间排序的数据结构</td><td>领取与处理中记录需要原子衔接</td></tr><tr><td>支持延迟投递的消息系统</td><td>消息代理</td><td>最大延迟、精度、持久化和确认规则</td></tr></tbody></table><p>Redis 有序集合支持按 score 排序与范围查询，可以用时间戳寻找候选任务；这是底层数据结构能力。若查询后直接删除，再交给 Worker，进程在中间崩溃就会丢失任务，需要额外设计处理中记录与恢复。参见 <a href="https://redis.io/docs/latest/develop/data-types/sorted-sets/" target="_blank" rel="noreferrer">Redis sorted sets</a>。</p><p>消息系统也不一定支持任意长的延迟。以当前 SQS 文档为例，延迟队列的最大延迟是 15 分钟，不能直接用它表达 30 分钟或数月后的所有任务。选型时应核对具体产品的限制，见 <a href="https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-delay-queues.html" target="_blank" rel="noreferrer">SQS delay queues</a>。</p><h2 id="gai-qi-yu-qu-xiao" tabindex="-1">改期与取消 <a class="header-anchor" href="#gai-qi-yu-qu-xiao" aria-label="Permalink to &quot;改期与取消&quot;">​</a></h2><p>预约由 10:00 改到 11:00 后，原提醒任务可能已经投递，不能只依赖删除旧消息。一个可追溯的设计是：</p><ol><li>业务事务更新预约时间并增加版本号。</li><li>同一事务保存新版本对应的提醒任务。</li><li>旧任务执行时读取预约，发现版本不匹配后记录为 <code>skipped</code>。</li></ol><p>业务键可以是 <code>appointment_id + reminder_type + version</code>。这样新旧计划各有独立记录，迟到的旧任务也能自行退出。版本号只应在影响该动作的业务变化时推进，避免无关更新使任务失效。</p><p>取消同样需要说明生效点：尚未开始的任务可以标记 <code>cancelled</code>；已经运行的任务需要处理器协作检查。邮件已经发送后，再更新取消标记无法撤回邮件。</p><h2 id="dao-qi-shi-chong-xin-pan-duan-tiao-jian" tabindex="-1">到期时重新判断条件 <a class="header-anchor" href="#dao-qi-shi-chong-xin-pan-duan-tiao-jian" aria-label="Permalink to &quot;到期时重新判断条件&quot;">​</a></h2><p>关闭订单时应在同一条写入语句里检查待支付状态、期限和相关版本，不能先读取“未支付”，随后无条件更新为“已关闭”。完整的并发路径见<a href="./../scenarios/order-timeout.html">订单超时关闭</a>。</p><p>对提醒任务，还需要判断消息是否仍有业务价值。例如会议已经结束，迟到的“还有 10 分钟开始”提醒应跳过，而不是为了提高成功率继续补发。</p><h2 id="yan-chi-tou-di-yu-zhi-xing-zu-yue" tabindex="-1">延迟投递与执行租约 <a class="header-anchor" href="#yan-chi-tou-di-yu-zhi-xing-zu-yue" aria-label="Permalink to &quot;延迟投递与执行租约&quot;">​</a></h2><p>延迟投递控制首次可见时间；执行租约控制领取之后何时可以被其他 Worker 再次领取。两者用途不同。</p><p>SQS 的<a href="https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-visibility-timeout.html" target="_blank" rel="noreferrer">可见性超时</a>发生在接收消息之后，超时且未删除的消息可以再次被接收。它的投递语义仍要求消费者处理重复；调整租约长度不能替代业务幂等。</p><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>Redis：<a href="https://redis.io/docs/latest/develop/data-types/sorted-sets/" target="_blank" rel="noreferrer">Sorted sets</a></li><li>Amazon SQS：<a href="https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-delay-queues.html" target="_blank" rel="noreferrer">Delay queues</a></li><li>Amazon SQS：<a href="https://docs.aws.amazon.com/AWSSimpleQueueService/latest/SQSDeveloperGuide/sqs-visibility-timeout.html" target="_blank" rel="noreferrer">Visibility timeout</a></li></ul>',23)])])}const m=t(r,[["render",o]]);export{p as __pageData,m as default};
